<script lang="ts">
import {useLocale} from '$lib/i18n';import Language from './Language.svelte';import {ArrowRight,Building2,Users,ShieldCheck,Sparkles} from 'lucide-svelte';import {goto} from '$app/navigation';
let {register=false}=$props();const {t}=useLocale();let name=$state(''),email=$state(''),password=$state(''),busy=$state(false),error=$state('');
async function submit(e:SubmitEvent){e.preventDefault();busy=true;error='';try{const r=await fetch(`/api/auth/${register?'sign-up':'sign-in'}/email`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,email,password})});const result=await r.json();if(!r.ok)throw new Error(result.message||t('Tidak dapat masuk. Periksa email dan kata sandi.','Unable to sign in. Check your email and password.'));await goto(register?'/onboarding':'/dashboard',{invalidateAll:true});}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<div class="auth-page"><section class="auth-story"><a class="brand" href="/login"><img src="/favicon.svg" alt=""/><div>ORVEXA<small>Your AI Workforce.</small></div></a><div class="story-main"><span class="eyebrow">BUILT FOR YOUR BUSINESS</span><h1>{t('Bisnis Anda.','Your business.')}<br/>{t('Tim AI Anda.','Your AI team.')}<br/><em>{t('Kemungkinan baru.','New possibilities.')}</em></h1><p>{t('Bangun tim karyawan AI yang mengenal bisnis Anda. Beri tujuan, biarkan mereka bekerja bersama, dan pantau hasilnya.','Build a team of AI employees that understands your business. Set a goal, let them collaborate, and follow the results.')}</p><div class="story-cards"><div><Building2 size={23}/><span>{t('Satu tempat untuk bisnis Anda','One home for your business')}</span></div><div><Users size={23}/><span>{t('Karyawan AI dengan peran yang jelas','AI employees with clear roles')}</span></div><div><ShieldCheck size={23}/><span>{t('Anda tetap memegang kendali','You stay in control')}</span></div></div></div><small>ORVEXA · {t('Ruang kerja baru untuk usaha Anda','A new workspace for your business')}</small></section><section class="auth-form-section"><div class="auth-top"><Language/></div><form class="auth-form" onsubmit={submit}><span class="form-icon"><Sparkles size={26}/></span><h2>{register?t('Mulai perjalanan Anda','Start your journey'):t('Selamat datang kembali','Welcome back')}</h2><p>{register?t('Buat akun owner untuk membangun tim AI Anda.','Create an owner account to build your AI team.'):t('Masuk untuk melihat bisnis dan tim Anda.','Sign in to your business and your team.')}</p>{#if error}<div class="alert error" role="alert">{error}</div>{/if}{#if register}<label>{t('Nama Anda','Your name')}<input required minlength="2" maxlength="100" bind:value={name} autocomplete="name" placeholder="Alex"/></label>{/if}<label>Email<input required type="email" bind:value={email} autocomplete="email" placeholder="you@company.com"/></label><label>{t('Kata sandi','Password')}<input required type="password" minlength="10" bind:value={password} autocomplete={register?'new-password':'current-password'} placeholder={t('Minimal 10 karakter','At least 10 characters')}/></label><button class="primary full" disabled={busy}>{busy?t('Memproses…','Please wait…'):register?t('Buat akun','Create account'):t('Masuk','Sign in')}<ArrowRight size={17}/></button><p class="auth-switch">{register?t('Sudah punya akun?','Already have an account?'):t('Belum punya akun?','New to ORVEXA?')} <a href={register?'/login':'/register'}>{register?t('Masuk','Sign in'):t('Buat akun','Create an account')}</a></p></form></section></div>
